function category(label: string, headline: string, description: string, providerSingular: string, providerPlural: string): CategoryCopy {
  return { label, headline, description, providerSingular, providerPlural };
}

export function marketplaceText(locale: Locale, english: string) {
  return locale === "en" ? english : UI_COPY[locale][english] ?? ACCOUNT_AND_EDITOR_COPY[locale][english] ?? english;
}

const PRICING_BASIS_LABELS: Record<string, string> = {
  session: "Per session",
  hour: "Per hour",
  class: "Per class",
  consultation: "Per consultation",
  week: "Per week",
  month: "Per month",
  package: "Per package",
};

function localizedCurrencyFormatter(locale: Locale, currency: string) {
  const languageTag = locale === "es-419" ? "es-419" : locale === "pt-BR" ? "pt-BR" : "en-US";
  return new Intl.NumberFormat(languageTag, {
    style: "currency",
    currency: currency || "USD",
    maximumFractionDigits: 0,
  });
}

function localizedPricingBasis(value: string | null, locale: Locale) {
  if (!value) return null;
  const label = PRICING_BASIS_LABELS[value.trim().toLowerCase()] ?? value;
  return marketplaceText(locale, label);
}

export function formatLocalizedProfessionalPrice(
  professional: Pick<ProfessionalProfileRecord, "priceFrom" | "priceTo" | "pricingBasis" | "pricingCurrency" | "contactForPricing">,
  locale: Locale,
) {
  if (professional.contactForPricing) return marketplaceText(locale, "Contact for pricing");
  if (professional.priceFrom == null) return null;

  const formatter = localizedCurrencyFormatter(locale, professional.pricingCurrency);
  const basis = localizedPricingBasis(professional.pricingBasis, locale);
  const suffix = basis ? ` · ${basis}` : "";

  if (professional.priceTo != null && professional.priceTo > professional.priceFrom) {
    return `${formatter.format(professional.priceFrom)}-${formatter.format(professional.priceTo)}${suffix}`;
  }

  return `${marketplaceText(locale, "From")} ${formatter.format(professional.priceFrom)}${suffix}`;
}

export function formatLocalizedServicePrice(
  service: Pick<ProfessionalServiceRecord, "price" | "priceTo" | "pricingBasis" | "contactForPricing" | "currencyCode">,
  locale: Locale,
) {
  if (service.contactForPricing) return marketplaceText(locale, "Contact for pricing");
  if (service.price == null) return null;

  const formatter = localizedCurrencyFormatter(locale, service.currencyCode);
  const basis = localizedPricingBasis(service.pricingBasis, locale);
  const suffix = basis ? ` · ${basis}` : "";

  if (service.priceTo != null && service.priceTo > service.price) {
    return `${formatter.format(service.price)}-${formatter.format(service.priceTo)}${suffix}`;
  }

  return `${formatter.format(service.price)}${suffix}`;
}

export function localizeMarketplaceLocation(value: string, locale: Locale) {
  if (value === "Online" || value === "Location flexible" || value === "Location not listed") {
    return marketplaceText(locale, value);
  }
  return value;
}

export function localizeMarketplaceCategory(categoryRecord: ProfessionalCategoryRecord, locale: Locale) {
  if (locale === "en") return categoryRecord;
  const copy = CATEGORY_COPY[locale][categoryRecord.publicSlug || categoryRecord.slug];
  return copy
    ? { ...categoryRecord, label: copy.label, headline: copy.headline, shortDescription: copy.description }
    : categoryRecord;
}

export function getMarketplaceCategoryCopy(slug: string, locale: Locale) {
  return locale === "en" ? null : CATEGORY_COPY[locale][slug] ?? null;
}

export function localizeMarketplaceSpecialty(value: string, locale: Locale) {
  return locale === "en" ? value : SPECIALTY_COPY[locale][value] ?? value;
}

export function formatMarketplaceYears(years: number | null, locale: Locale) {
  if (years == null) return null;
  if (locale === "es-419") return `${years} ${years === 1 ? "año" : "años"} de experiencia`;
  if (locale === "pt-BR") return `${years} ${years === 1 ? "ano" : "anos"} de experiência`;
  return `${years} ${years === 1 ? "year" : "years"} experience`;
}

export function localizeServiceMode(value: string, locale: Locale) {
  const normalized = value.toLowerCase();
  if (normalized === "in_person") return marketplaceText(locale, "In person");
  if (normalized === "online") return marketplaceText(locale, "Online");
  if (normalized === "hybrid") return marketplaceText(locale, "Hybrid");
  return marketplaceText(locale, "Flexible");
}

export function localizeApprovalStatus(value: string, locale: Locale) {
  const status = value.toLowerCase();
  if (locale === "es-419") return ({ approved: "Aprobado", verified: "Aprobado", pending: "En revisión", pending_review: "En revisión", rejected: "Cambios requeridos", draft: "Borrador", suspended: "Suspendido", inactive: "Inactivo" } as TranslationDictionary)[status] ?? value;
  if (locale === "pt-BR") return ({ approved: "Aprovado", verified: "Aprovado", pending: "Em análise", pending_review: "Em análise", rejected: "Alterações necessárias", draft: "Rascunho", suspended: "Suspenso", inactive: "Inativo" } as TranslationDictionary)[status] ?? value;
  return value;
}

export function localizeProfessionalPath(pathname: string, locale: Locale) {
  return localizePathname(pathname, locale);
}

export function buildLocalizedCategoryFaqs(categoryRecord: ProfessionalCategoryRecord, locale: Locale) {
  const copy = getMarketplaceCategoryCopy(categoryRecord.publicSlug || categoryRecord.slug, locale);
  if (!copy) return null;
  if (locale === "es-419") return [
    { question: `¿Qué debo considerar al contratar a un ${copy.providerSingular}?`, answer: "Compara experiencia relevante, especialidades, modalidad, precios, credenciales cuando correspondan y un estilo de comunicación compatible con tus objetivos." },
    { question: `¿Puedo explorar perfiles de ${copy.providerPlural} antes de crear una cuenta?`, answer: "Sí. El directorio público y los perfiles publicados se pueden explorar antes de iniciar sesión." },
    { question: `¿Todos los ${copy.providerPlural} trabajan de la misma manera?`, answer: "No. Algunos ofrecen sesiones presenciales, otros trabajan en línea y otros usan modelos híbridos con precios y estructuras diferentes." },
    { question: "¿Cómo solicito una consulta en Elevare?", answer: "Abre un perfil, selecciona Solicitar consulta y envía una solicitud breve." },
  ];
  return [
    { question: `O que devo avaliar ao contratar um ${copy.providerSingular}?`, answer: "Compare experiência relevante, especialidades, modalidade, preços, credenciais quando aplicável e um estilo de comunicação alinhado aos seus objetivos." },
    { question: `Posso explorar perfis de ${copy.providerPlural} antes de criar uma conta?`, answer: "Sim. O diretório público e os perfis publicados podem ser consultados antes de entrar." },
    { question: `Todos os ${copy.providerPlural} trabalham da mesma forma?`, answer: "Não. Alguns oferecem sessões presenciais, outros trabalham online e outros usam modelos híbridos com preços e estruturas diferentes." },
    { question: "Como solicito uma consulta na Elevare?", answer: "Abra um perfil, selecione Solicitar consulta e envie uma solicitação breve." },
  ];
}

export function getLocalizedProfessionalMetadataCopy(locale: Locale, name: string, role: string, location: string) {
  if (locale === "es-419") return { title: `${name}: ${role} | Elevare`, description: `Consulta los servicios, especialidades, credenciales y disponibilidad de ${name}${location ? ` en ${location}` : ""} en Elevare.` };
  if (locale === "pt-BR") return { title: `${name}: ${role} | Elevare`, description: `Veja os serviços, especialidades, credenciais e disponibilidade de ${name}${location ? ` em ${location}` : ""} na Elevare.` };
  return { title: `${name}: ${role} | Elevare`, description: `View ${name}'s services, specialties, credentials, and availability${location ? ` in ${location}` : ""} on Elevare.` };
}
